-- ==========================================================================
-- supabase/seed.sql - Pracuj.be DANE DEMONSTRACYJNE (is_demo = true)
-- ==========================================================================
--
-- Zakres: 10 firm, 50 ofert (+ tlumaczenia pl/nl/fr/en dla czesci),
--         40 kandydatow, aplikacje, propozycje (offers), wiadomosci,
--         powiadomienia, wyniki dopasowan (matches) oraz slowniki i dane
--         okoloprocesowe (pliki, zgody, subskrypcje, faktury, audyt).
--
-- WYMAGANIA / ZALOZENIA:
--   * Uruchamiac PO migracjach 0001-0008 (schemat + enumy + triggery).
--   * Kandydaci/pracodawcy wymagaja wpisow w auth.users. Ten seed TWORZY
--     uzytkownikow auth (lokalny Supabase na to pozwala) z bezpiecznym
--     haslem demo: 'DemoPass123!' (dla wszystkich kont demonstracyjnych).
--     Trigger handle_new_user() automatycznie zaklada wiersze w profiles
--     oraz notification_preferences; ponizej UZUPELNIAMY je (upsert).
--     Jesli w danym srodowisku nie mozna pisac do auth.users, nalezy
--     najpierw utworzyc uzytkownikow o ponizszych UUID innym sposobem.
--   * Deterministyczne UUID (00000000-0000-0000-0000-0000<TT><NNNNNN>)
--     zapewniaja powtarzalnosc. Wszystkie INSERT-y sa idempotentne
--     (ON CONFLICT DO NOTHING / DO UPDATE) - seed mozna uruchamiac wielokrotnie.
--   * pgcrypto (crypt/gen_salt) pochodzi z migracji 0001.
--
begin;

-- ==========================================================================
-- SEC-17: bezpiecznik przed przypadkowym seedem DEMO na staging/produkcji.
-- Seed tworzy konta o znanym haśle ('DemoPass123!'), więc NIE wolno go uruchomić
-- na bazie z realnymi danymi. Odmawiamy, jeśli istnieją realne (nie-demo) firmy lub oferty.
-- Na czystej/lokalnej/CI bazie (0 realnych rekordów) przechodzi normalnie; ponowny seed też
-- (dane demo mają is_demo=true). Cały seed jest w jednej transakcji — abort = pełny rollback.
-- ==========================================================================
do $$
declare v_real_companies int; v_real_jobs int;
begin
  select count(*) into v_real_companies from public.companies where is_demo = false;
  select count(*) into v_real_jobs from public.jobs where is_demo = false;
  if v_real_companies > 0 or v_real_jobs > 0 then
    raise exception
      'SEED DEMO odmowa (SEC-17): baza zawiera realne dane (firmy=%, oferty=%). Seed tylko na czystej/lokalnej bazie.',
      v_real_companies, v_real_jobs using errcode = '42501';
  end if;
end $$;

