-- ==========================================================================
-- auth.identities - tozsamosci email (best-effort)
-- ==========================================================================
-- Opakowane w DO/EXCEPTION: rozne wersje Supabase maja rozny uklad kolumn.
do $$ begin
  execute $ident$
    on conflict do nothing
  $ident$;
exception when others then raise notice 'auth.identities pominiete: %', sqlerrm; end $$;

